class ParameterNotFound(Exception):
    """
    Raised when pcap or syslog parameter cannot be found.
    """


class PcapDataNotFound(Exception):
    """
    Raised when particular data not found in pcap.
    """


class IncorrectParameterName(Exception):
    """
    Raised when pcap or syslog parameter name is incorrect.
    """


class IncorrectParameterValue(Exception):
    """
    Raised when pcap or syslog parameter value is incorrect.
    """


class ConfigurationNotSupported(Exception):
    """
    Raised when provided configuration is not supported
    """


class SOAPValidationError(Exception):
    """
    Raised when SOAP validation failed.
    """


class IncorrectFileExtension(Exception):
    """
    Raised when provided file has incorrect extension.
    """


class CoreDumpDecodingError(Exception):
    """
    Raised when Core Dump decoding has failed.
    """


class TimeExtractionError(Exception):
    """
    Raised when time extraction from syslog line has failed.
    """


class NoMatchingLinesFoundError(Exception):
    """
    Raised when no matching lines are found in the syslog using the provided filters.
    """


class BtsSyslogError(Exception):
    """
    Raised when BTS syslog contains error messages.
    """
